/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountRegroupingBubbles, type RegroupingBubblesOptions } from "../../components/regrouping-bubbles/RegroupingBubblesEngine.js";
import type { MotionController } from "../../components/regrouping-bubbles/motion-runtime";

export function RegroupingBubbles({ options, className }: { options?: RegroupingBubblesOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountRegroupingBubbles(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="regrouping-bubbles" />;
}

